module tb;

  // -----------------------------------------------------------------
  // Parameters and signals
  // -----------------------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz
  logic clk = 1'b0;
  logic rst = 1'b0;
  logic rxd = 1'b1;
  logic [15:0] prescale_val = 16'd1;
  logic [7:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready;
  logic [7:0] txd;
  logic [7:0] rx_busy;
  logic [7:0] s_axis_tdata = 8'd0;
  logic        s_axis_tvalid = 1'b0;
  logic        s_axis_tready_dummy;
  wire       m_axis_tready_wire;
  assign m_axis_tready_wire = 1'b1; // always ready for AXI output
  wire tx_busy_dummy;
  wire rx_overrun_error_dummy;
  wire rx_frame_error_dummy;

  // -----------------------------------------------------------------
  // DUT instantiation
  // -----------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready_dummy),
    .txd          (txd),
    .tx_busy      (tx_busy_dummy),
    .rx_busy      (rx_busy),
    .rx_overrun_error(rx_overrun_error_dummy),
    .rx_frame_error(rx_frame_error_dummy),
    .prescale     (prescale_val),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready_wire)
  );

  // -----------------------------------------------------------------
  // Helper tasks
  // -----------------------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic uart_send_byte(input byte unsigned b);
    int unsigned bit_clks = prescale_val * 8;
    // start bit
    rxd = 1'b0;
    wait_clks(bit_clks);
    // data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(bit_clks);
    end
    // stop bit
    rxd = 1'b1;
    wait_clks(bit_clks);
    // idle (high)
    rxd = 1'b1;
  endtask

  task automatic do_reset();
    rst = 1'b1;
    wait_clks(2);
    rst = 1'b0;
    wait_clks(2);
    rst = 1'b0;
    wait_clks(2);
  endtask

  task automatic send_and_capture(input byte unsigned data);
    // Wait until receiver is idle
    while (rx_busy) @(negedge clk);
    // Transmit the byte on rxd
    uart_send_byte(data);
    // Give the DUT some time to present the word on m_axis_tvalid
    repeat (50) @(negedge clk);
  endtask

  // -----------------------------------------------------------------
  // Main stimulus
  // -----------------------------------------------------------------
  initial begin
    // Clock generation
    forever #(CLK_PERIOD/2) clk = ~clk;

    // Reset the design
    do_reset();

    // -------------------------------------------------------------
    // 1) Capture a frame at prescale = 1  (expected data 0xA5)
    // -------------------------------------------------------------
    @(negedge clk);
    prescale_val = 16'd1;                 // ensure prescale is 1
    send_and_capture(8'hA5);               // send 0xA5

    // -------------------------------------------------------------
    // 2) Change prescale to 2 while the receiver is idle,
    //    then capture a second frame with data 0x5A
    // -------------------------------------------------------------
    while (rx_busy) @(negedge clk);      // wait for idle
    @(negedge clk);
    prescale_val = 16'd2;                 // switch prescale
    repeat (4) @(negedge clk);           // small idle delay

    send_and_capture(8'h5A);               // transmit 0x5A

    // -------------------------------------------------------------
    // 3) End of simulation
    // -------------------------------------------------------------
    $finish;
  end

endmodule

module tb;

  // ------------------------------------------------------------
  //  Parameters
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz

  // ------------------------------------------------------------
  //  Clock generation
  // ------------------------------------------------------------
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  //  Reset
  // ------------------------------------------------------------
  logic rst = 0;

  // ------------------------------------------------------------
  //  DUT signal declarations
  // ------------------------------------------------------------
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  logic       s_axis_tready;   // output of DUT
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready;   // input to DUT (tied to 1)

  logic txd;
  logic tx_busy;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;
  logic [15:0] prescale_val;

  // Drive rxd
  reg rxd_drv;

  // ------------------------------------------------------------
  //  DUT instantiation
  // ------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),

    // AXI input
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),

    // AXI output
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),

    // UART interface
    .rxd          (rxd_drv),
    .txd          (txd),

    // Status
    .tx_busy      (tx_busy),
    .rx_busy      (rx_busy),
    .rx_overrun_error (rx_overrun_error),
    .rx_frame_error   (rx_frame_error),

    // Configuration
    .prescale     (prescale_val)
  );

  // ------------------------------------------------------------
  //  Tie off unused or unneeded signals
  // ------------------------------------------------------------
  assign m_axis_tready = 1'b1;                // always ready
  assign s_axis_tdata  = 8'h00;               // idle data
  assign s_axis_tvalid = 1'b0;                // never drive TACVALID

  // ------------------------------------------------------------
  //  Reset task
  // ------------------------------------------------------------
  task automatic do_reset();
    rst = 0;
    repeat (2) @(posedge clk);
    rst = 1;
    repeat (2) @(posedge clk);
    rst = 0;
    repeat (2) @(posedge clk);
  endtask

  // ------------------------------------------------------------
  //  Frame transmission task (LSB‑first)
  // ------------------------------------------------------------
  task automatic send_frame(input byte unsigned data_byte);
    int bc;
    bc = prescale_val * 8;

    // Start bit (low)
    rxd_drv = 1'b0;
    for (int i = 0; i < bc; i = i + 1) @(posedge clk);

    // Data bits, LSB first
    for (int i = 0; i < 8; i = i + 1) begin
      rxd_drv = data_byte[i];
      for (int j = 0; j < bc; j = j + 1) @(posedge clk);
    end

    // Stop bit (high)
    rxd_drv = 1'b1;
    for (int k = 0; k < bc; k = k + 1) @(posedge clk);
  endtask

  // ------------------------------------------------------------
  //  Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Initialise configuration
    prescale_val = 16'd1;

    // Reset the DUT
    do_reset();

    // ------------------------------------------------------------
    // 1) Send 0xA5 while prescale = 1
    // ------------------------------------------------------------
    repeat (4) @(posedge clk);               // small idle after reset
    send_frame(8'hA5);                        // first frame

    // Wait until the receiver is idle (busy goes low)
    repeat (150) @(posedge clk);

    // Change prescale to 2 while busy is low (allowed)
    prescale_val = 16'd2;
    repeat (5) @(posedge clk);               // small idle

    // ------------------------------------------------------------
    // 2) Send 0x5A while prescale = 2
    // ------------------------------------------------------------
    send_frame(8'h5A);                        // second frame

    // Give the design time to present m_axis_tvalid/frame_error
    repeat (200) @(posedge clk);

    $display("Simulation completed");
    $finish;
  end

endmodule
